-- Learning path schema populated from career_stage_courses_30_roles_6_stages.sql.
-- The generated seed uses one reusable stage_id per stage number, so stages are
-- normalized per career with fresh UUIDs before courses are attached.

CREATE TABLE IF NOT EXISTS learning_paths (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    career_identifier TEXT UNIQUE,
    career_name VARCHAR(255) NOT NULL UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    total_stages INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS stages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    learning_path_id UUID NOT NULL REFERENCES learning_paths(id) ON DELETE CASCADE,
    stage_number INT NOT NULL,
    stage_identifier TEXT,
    title VARCHAR(255) NOT NULL,
    subtitle TEXT NOT NULL DEFAULT '',
    position_top VARCHAR(50),
    position_left VARCHAR(50),
    position_right VARCHAR(50),
    position_bottom VARCHAR(50),
    position_transform VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(learning_path_id, stage_number)
);

CREATE TABLE IF NOT EXISTS courses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    stage_id UUID NOT NULL REFERENCES stages(id) ON DELETE CASCADE,
    course_identifier TEXT UNIQUE,
    title VARCHAR(500) NOT NULL,
    subtitle TEXT NOT NULL DEFAULT '',
    source_code TEXT,
    source_name TEXT,
    cost_type TEXT,
    url TEXT,
    sort_order INT NOT NULL DEFAULT 0,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS user_stage_progress (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    stage_id UUID NOT NULL REFERENCES stages(id) ON DELETE CASCADE,
    status VARCHAR(50) NOT NULL DEFAULT 'locked',
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(user_id, stage_id),
    CHECK (status IN ('locked', 'in-progress', 'completed'))
);

CREATE INDEX IF NOT EXISTS idx_learning_paths_career_name ON learning_paths(career_name);
CREATE INDEX IF NOT EXISTS idx_learning_paths_career_identifier ON learning_paths(career_identifier);
CREATE INDEX IF NOT EXISTS idx_stages_learning_path_id ON stages(learning_path_id);
CREATE INDEX IF NOT EXISTS idx_stages_stage_identifier ON stages(stage_identifier);
CREATE INDEX IF NOT EXISTS idx_courses_stage_id ON courses(stage_id);
CREATE INDEX IF NOT EXISTS idx_courses_course_identifier ON courses(course_identifier);
CREATE INDEX IF NOT EXISTS idx_user_stage_progress_user_id ON user_stage_progress(user_id);
CREATE INDEX IF NOT EXISTS idx_user_stage_progress_stage_id ON user_stage_progress(stage_id);

DROP TABLE IF EXISTS tmp_career_stage_courses;

-- Generated seed file: 30 careers x 6 stages x 6 courses = 1080 rows
-- Loaded into a temp table, then normalized into learning_paths/stages/courses.

CREATE TEMP TABLE tmp_career_stage_courses (
  course_identifier TEXT PRIMARY KEY,
  career_identifier TEXT NOT NULL,
  career_name TEXT NOT NULL,
  stage_id TEXT NOT NULL,
  stage_number INTEGER NOT NULL,
  stage_identifier TEXT NOT NULL,
  stage_name TEXT NOT NULL,
  title TEXT NOT NULL,
  subtitle_th TEXT,
  source_code TEXT,
  source_name TEXT,
  cost_type TEXT,
  url TEXT,
  sort_order INTEGER,
  notes TEXT
);



SELECT
    gen_random_uuid(),
    career_identifier,
    career_name,
    'Learning path with 6 stages for ' || career_name,
    MAX(stage_number)
FROM tmp_career_stage_courses
GROUP BY career_identifier, career_name
ON CONFLICT (career_name) DO UPDATE SET
    career_identifier = EXCLUDED.career_identifier,
    description = EXCLUDED.description,
    total_stages = EXCLUDED.total_stages,
    updated_at = NOW();

WITH seed_stages AS (
    SELECT DISTINCT
        career_identifier,
        career_name,
        stage_number,
        stage_identifier,
        stage_name
    FROM tmp_career_stage_courses
)
    id,
    learning_path_id,
    stage_number,
    stage_identifier,
    title,
    subtitle,
    position_top,
    position_left,
    position_right,
    position_bottom,
    position_transform
)
SELECT
    gen_random_uuid(),
    lp.id,
    ss.stage_number,
    ss.stage_identifier,
    ss.stage_name,
    CASE ss.stage_number
        WHEN 1 THEN 'Start with core foundations'
        WHEN 2 THEN 'Build core knowledge'
        WHEN 3 THEN 'Practice essential job skills'
        WHEN 4 THEN 'Deepen specialized skills'
        WHEN 5 THEN 'Create portfolio work'
        WHEN 6 THEN 'Prepare for career launch'
        ELSE ss.stage_name
    END,
    CASE ss.stage_number WHEN 1 THEN '1%' WHEN 2 THEN '17%' WHEN 3 THEN '26%' WHEN 4 THEN '38%' ELSE NULL END,
    CASE ss.stage_number WHEN 1 THEN '62%' WHEN 4 THEN '23%' WHEN 6 THEN '25%' ELSE NULL END,
    CASE ss.stage_number WHEN 2 THEN '55%' WHEN 3 THEN '15%' WHEN 5 THEN '23%' ELSE NULL END,
    CASE ss.stage_number WHEN 5 THEN '33%' WHEN 6 THEN '3%' ELSE NULL END,
    CASE ss.stage_number WHEN 1 THEN 'translateX(-50%)' ELSE NULL END
FROM seed_stages ss
JOIN learning_paths lp ON lp.career_name = ss.career_name
ON CONFLICT (learning_path_id, stage_number) DO UPDATE SET
    stage_identifier = EXCLUDED.stage_identifier,
    title = EXCLUDED.title,
    subtitle = EXCLUDED.subtitle,
    position_top = EXCLUDED.position_top,
    position_left = EXCLUDED.position_left,
    position_right = EXCLUDED.position_right,
    position_bottom = EXCLUDED.position_bottom,
    position_transform = EXCLUDED.position_transform,
    updated_at = NOW();

    id,
    stage_id,
    course_identifier,
    title,
    subtitle,
    source_code,
    source_name,
    cost_type,
    url,
    sort_order,
    notes
)
SELECT
    gen_random_uuid(),
    s.id,
    c.course_identifier,
    c.title,
    COALESCE(c.subtitle_th, ''),
    c.source_code,
    c.source_name,
    c.cost_type,
    c.url,
    COALESCE(c.sort_order, 0),
    c.notes
FROM tmp_career_stage_courses c
JOIN learning_paths lp ON lp.career_name = c.career_name
JOIN stages s ON s.learning_path_id = lp.id AND s.stage_number = c.stage_number
ON CONFLICT (course_identifier) DO UPDATE SET
    stage_id = EXCLUDED.stage_id,
    title = EXCLUDED.title,
    subtitle = EXCLUDED.subtitle,
    source_code = EXCLUDED.source_code,
    source_name = EXCLUDED.source_name,
    cost_type = EXCLUDED.cost_type,
    url = EXCLUDED.url,
    sort_order = EXCLUDED.sort_order,
    notes = EXCLUDED.notes,
    updated_at = NOW();

DROP TABLE IF EXISTS tmp_career_stage_courses;
